package wgmodern;
import com.mojang.blaze3d.vertex.PoseStack;import net.minecraft.client.model.*;import net.minecraft.client.renderer.*;import net.minecraft.client.renderer.entity.RenderLayerParent;import net.minecraft.world.entity.LivingEntity;import net.minecraft.world.item.ItemStack;import top.theillusivec4.curios.api.SlotContext;import vazkii.botania.api.item.CosmeticAttachable;import vazkii.botania.client.render.AccessoryRenderRegistry;
public class BotaniaCosmeticRenderer {
 public static <T extends LivingEntity,M extends EntityModel<T>> boolean render(ItemStack stack,SlotContext context,PoseStack pose,RenderLayerParent<T,M> parent,MultiBufferSource buffers,int light,float swing,float amount,float partial,float age,float yaw,float pitch){if(!(stack.getItem() instanceof CosmeticAttachable attachable)||!(parent.getModel() instanceof HumanoidModel<?> human))return false;var cosmetic=attachable.getCosmeticItem(stack);if(cosmetic.isEmpty())return false;var renderer=AccessoryRenderRegistry.get(cosmetic);if(renderer==null)return false;pose.pushPose();try{renderer.doRender(human,cosmetic,context.entity(),pose,buffers,light,swing,amount,partial,age,yaw,pitch);}finally{pose.popPose();}return true;}
}
